package com.foodbridge.donor;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@Controller @RequestMapping("/donor/staff-accounts")
public class DonorStaffController {
    private final DonorOrganizationRepository orgs;private final DonorStaffAccountRepository staff;private final org.springframework.security.crypto.password.PasswordEncoder encoder;
    public DonorStaffController(DonorOrganizationRepository orgs,DonorStaffAccountRepository staff,org.springframework.security.crypto.password.PasswordEncoder encoder){this.orgs=orgs;this.staff=staff;this.encoder=encoder;}
    @GetMapping public String list(Model m){DonorOrganization org=ensureDemoOrganization();m.addAttribute("organization",org);m.addAttribute("staffAccounts",staff.findByOrganizationIdOrderByCreatedAtDesc(org.getId()));m.addAttribute("form",new StaffForm());return "donor/staff-accounts";}
    @PostMapping public String add(@Valid @ModelAttribute("form") StaffForm form,org.springframework.validation.BindingResult errors,Model m){DonorOrganization org=ensureDemoOrganization();if(staff.existsByOrganizationIdAndEmail(org.getId(),form.email().toLowerCase().trim()))errors.rejectValue("email","duplicate","This email already exists for this donor organization.");if(errors.hasErrors()){m.addAttribute("organization",org);m.addAttribute("staffAccounts",staff.findByOrganizationIdOrderByCreatedAtDesc(org.getId()));return "donor/staff-accounts";}staff.save(new DonorStaffAccount(org,form.email(),form.fullName(),form.jobTitle(),encoder.encode(form.password())));return "redirect:/donor/staff-accounts";}
    @PostMapping("/{id}/active") public String active(@PathVariable long id,@RequestParam boolean value){DonorOrganization org=ensureDemoOrganization();DonorStaffAccount s=staff.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!s.getOrganization().getId().equals(org.getId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND);s.setActive(value);staff.save(s);return "redirect:/donor/staff-accounts";}
    private DonorOrganization ensureDemoOrganization(){return orgs.findAll().stream().findFirst().orElseGet(()->orgs.save(new DonorOrganization("Demo Donor Organization","Dhaka, Bangladesh")));}
    public static class StaffForm { @NotBlank @Email private String email=""; @NotBlank @Size(max=100) private String fullName=""; @NotBlank @Size(max=80) private String jobTitle="Donor staff"; @NotBlank @Size(min=8,max=72) private String password=""; public String email(){return email;} public String fullName(){return fullName;} public String jobTitle(){return jobTitle;} public String password(){return password;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getJobTitle(){return jobTitle;} public void setJobTitle(String v){jobTitle=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} }
}
